import{_ as i,l as o,o as e,c as l,v as r,p as n,x as t,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"服务发现","description":"","frontmatter":{"title":"服务发现","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/service-discovery.md","filePath":"cs/service-discovery.md","lastUpdated":1789023840000}'),h={name:"cs/service-discovery.md"};function T(_,a,B,E,m,D){const s=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="服务发现" tabindex="-1">服务发现 <a class="header-anchor" href="#服务发现" aria-label="Permalink to &quot;服务发现&quot;">​</a></h1><div class="epigraph"><p>实例上下线比 DNS TTL 快；发现把名字映到健康地址集合，LB 再从中选。DNS、注册表、网格是三条路。</p><footer>—— 据 RFC 1035 对照；微服务发现实践整理</footer></div><p><a href="/cs/dns-cache-ttl">DNS TTL</a> 太慢跟不上容器。<a href="/cs/reverse-proxy">反向代理</a> 需要后端列表。<a href="/cs/reverse-proxy">上一课</a> 假定池已知。缺口是<strong>发现</strong>：注册、健康、订阅。本课结束实时与分发课序。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>虚拟机/容器秒级生灭。权威 DNS + 60 s TTL 会指向死 IP。服务发现：实例启动向注册表报，心跳，代理 watch 变化。DNS 仍可用于粗入口。gRPC 客户端也可直连发现。与 BGP 对照：都是通告可达，一层应用实例，一层前缀。EVPN Type 2 是数据中心版 MAC 发现。</p><p>不要把 Kubernetes 当唯一标准。</p><p><span class="marginnote">接口因平台而异。本课钉问题：比 DNS 更短的生命周期。</span></p><h3 id="比-dns-ttl-更短的生命周期" tabindex="-1">比 DNS TTL 更短的生命周期 <a class="header-anchor" href="#比-dns-ttl-更短的生命周期" aria-label="Permalink to &quot;比 DNS TTL 更短的生命周期&quot;">​</a></h3><p>注册加心跳更新池。无健康检查只是更快的错误 DNS。注册表分区会脑裂。未认证注册像劫持。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：DNS / 注册表 / sidecar 网格。画：注册 → 健康 → 推送到 LB。与 Maglev 表更新衔接。</p>',11)),(e(),n(c,null,{default:t(()=>[p(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20REG%5B%22%E5%AE%9E%E4%BE%8B%E6%B3%A8%E5%86%8C%22%5D%20--%3E%20HB%5B%22%E5%BF%83%E8%B7%B3%22%5D%0A%20%20HB%20--%3E%20LB%5B%22%E6%9B%B4%E6%96%B0%E5%90%8E%E7%AB%AF%E9%9B%86%E5%90%88%22%5D%0A%20%20DNS%5B%22%E7%B2%97%20DNS%22%5D%20--%3E%20ENT%5B%22%E5%85%A5%E5%8F%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>失败：注册表分区造成脑裂双池。与 iBGP RR 同类风险。GeoDNS 发现的是 POP，不是 pod。PTP 无。安全：未认证注册会把流量拐走，像 BGP 劫持的数据中心版。</p><p>客户端负载均衡 vs 代理：状态放哪。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入某注册表 API 全文。ping/iperf 是下一课序第一课。后课默认：发现提供健康实例集；DNS TTL 不够细。</p><p>无健康检查的发现只是更快的错误 DNS。</p><p>上一课留下的缺口在本课收口；「服务发现」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/network-measurement">ping / iperf</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实例生命周期短于 DNS TTL。</li><li>注册+心跳更新 LB 池。</li><li>控制面可用性决定数据面正确。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：DNS 对照；服务发现实践。</li></ul>',10))])}const u=i(h,[["render",T]]);export{f as __pageData,u as default};
